#!/nix/store/3n4qphl9s728sz8frmpqqrv9b1m87g68-python3-3.14.7/bin/python
import json
import sqlite3
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import unquote, urlsplit

DB_PATH = "/var/lib/job-queue/jobs.sqlite3"


def open_db():
    db = sqlite3.connect(DB_PATH, timeout=30)
    db.execute("PRAGMA busy_timeout=30000")
    return db


class QueueHandler(BaseHTTPRequestHandler):
    protocol_version = "HTTP/1.1"

    def log_message(self, format, *args):
        return

    def send_bytes(self, status, body, content_type):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def job_id(self):
        path = urlsplit(self.path).path
        prefix = "/jobs/"
        if not path.startswith(prefix):
            return None
        encoded_id = path[len(prefix):]
        if not encoded_id or "/" in encoded_id:
            return None
        return unquote(encoded_id)

    def do_GET(self):
        if urlsplit(self.path).path == "/health":
            self.send_bytes(200, b"ready", "text/plain; charset=utf-8")
            return

        job_id = self.job_id()
        if job_id is None:
            self.send_bytes(404, b"not found", "text/plain; charset=utf-8")
            return

        try:
            with open_db() as db:
                row = db.execute(
                    "SELECT id, payload, status, result, attempts "
                    "FROM jobs WHERE id = ?",
                    (job_id,),
                ).fetchone()
        except sqlite3.Error:
            self.send_bytes(503, b"database unavailable", "text/plain; charset=utf-8")
            return

        if row is None:
            self.send_bytes(404, b"not found", "text/plain; charset=utf-8")
            return

        body = json.dumps(
            {
                "id": row[0],
                "payload": row[1],
                "status": row[2],
                "result": row[3],
                "attempts": int(row[4]),
            },
            ensure_ascii=False,
            separators=(",", ":"),
        ).encode("utf-8")
        self.send_bytes(200, body, "application/json; charset=utf-8")

    def do_POST(self):
        job_id = self.job_id()
        if job_id is None:
            self.send_bytes(404, b"not found", "text/plain; charset=utf-8")
            return

        try:
            length = int(self.headers.get("Content-Length", "-1"))
            if length < 0:
                raise ValueError
            payload = self.rfile.read(length).decode("utf-8", errors="strict")
        except (ValueError, UnicodeDecodeError):
            self.send_bytes(400, b"invalid UTF-8 request body", "text/plain; charset=utf-8")
            return

        try:
            with open_db() as db:
                db.execute(
                    "INSERT OR IGNORE INTO jobs "
                    "(id, payload, status, result, attempts) "
                    "VALUES (?, ?, 'queued', NULL, 0)",
                    (job_id, payload),
                )
                db.commit()
        except sqlite3.Error:
            self.send_bytes(503, b"database unavailable", "text/plain; charset=utf-8")
            return

        self.send_bytes(202, b"", "text/plain; charset=utf-8")


if __name__ == "__main__":
    server = ThreadingHTTPServer(("0.0.0.0", 8080), QueueHandler)
    try:
        server.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        server.server_close()

#!/nix/store/3n4qphl9s728sz8frmpqqrv9b1m87g68-python3-3.14.7/bin/python
import signal
import sqlite3
import threading
import time

DB_PATH = "/var/lib/job-queue/jobs.sqlite3"
stop = threading.Event()


def request_stop(signum, frame):
    stop.set()


def open_db():
    db = sqlite3.connect(DB_PATH, timeout=30, isolation_level=None)
    db.execute("PRAGMA busy_timeout=30000")
    return db


def process_one(db):
    db.execute("BEGIN IMMEDIATE")
    try:
        row = db.execute(
            "SELECT id, payload FROM jobs "
            "WHERE status = 'queued' AND attempts = 0 "
            "ORDER BY rowid LIMIT 1"
        ).fetchone()
        if row is None:
            row = db.execute(
                "SELECT id, payload FROM jobs "
                "WHERE status = 'processing' AND attempts = 1 "
                "ORDER BY rowid LIMIT 1"
            ).fetchone()

        if row is None:
            db.rollback()
            return False

        job_id, payload = row
        db.execute(
            "UPDATE jobs SET status = 'completed', result = ?, attempts = 1 "
            "WHERE id = ? AND attempts IN (0, 1) "
            "AND status IN ('queued', 'processing')",
            ("processed:" + payload, job_id),
        )
        db.commit()
        return True
    except Exception:
        db.rollback()
        raise


def main():
    signal.signal(signal.SIGTERM, request_stop)
    signal.signal(signal.SIGINT, request_stop)
    db = open_db()
    try:
        while not stop.is_set():
            try:
                if not process_one(db):
                    stop.wait(0.05)
            except sqlite3.Error:
                if stop.wait(0.1):
                    break
    finally:
        db.close()


if __name__ == "__main__":
    main()

